<?php ob_start(); ?><h1>Finding #<?= e($finding['id'] ?? '') ?></h1><?php if(!$finding): ?><p>Not found.</p><?php else: ?><div class="card"><p><b>Path:</b> <code><?= e($finding['path']) ?></code></p><p><b>Risk:</b> <span class="badge <?= e($finding['risk']) ?>"><?= e($finding['risk']) ?></span> <b>Type:</b> <?= e($finding['type']) ?> <b>Status:</b> <?= e($finding['status']) ?></p><p><b>SHA256:</b> <code><?= e($finding['sha256']) ?></code></p><p><b>Size:</b> <?= e($finding['size']) ?> <b>mtime:</b> <?= e($finding['mtime']) ?> <b>owner:</b> <?= e($finding['owner']) ?> <b>permissions:</b> <?= e($finding['permissions']) ?></p><p><b>Matched rules:</b></p><pre><?= e(json_encode(json_decode($finding['matched_rules'] ?: '[]', true), JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE)) ?></pre><form method="post" action="/finding/ignore" style="display:inline"><input type="hidden" name="id" value="<?= e($finding['id']) ?>"><button class="btn">Ignore</button></form> <form method="post" action="/finding/allowlist" style="display:inline"><input type="hidden" name="id" value="<?= e($finding['id']) ?>"><button class="btn">Allowlist</button></form><?php if(config('guard.web_actions_enabled')): ?> <form method="post" action="/finding/quarantine" onsubmit="return confirm('Move file to quarantine?')" style="display:inline"><input type="hidden" name="id" value="<?= e($finding['id']) ?>"><button class="btn danger">Quarantine</button></form><?php else: ?><p>Web actions disabled. Use CLI: <code>php artisan guard:quarantine <?= e($finding['id']) ?></code></p><?php endif ?></div><div class="card"><h2>Safe preview</h2><pre><?= e($preview ?: 'Preview unavailable or empty.') ?></pre></div><div class="card"><h2>Related log events</h2><table><tr><th>Risk</th><th>IP</th><th>URI</th><th>Raw</th></tr><?php foreach($events as $l): ?><tr><td><?= e($l['risk']) ?></td><td><?= e($l['ip']) ?></td><td><?= e($l['uri']) ?></td><td><?= e($l['raw_line']) ?></td></tr><?php endforeach ?></table></div><?php endif ?><?php $content=ob_get_clean(); include base_path('resources/views/layouts/app.php'); ?>
